import { Injectable } from '@angular/core';
import { Person, Transaction } from '../models/person.model';

@Injectable({
  providedIn: 'root'
})
export class ReceiptService {

generatePersonReceipt(person: Person): void {
  const canvas = document.createElement('canvas');
  canvas.width = 900;
  canvas.height = 1000;
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 32px Arial';
  ctx.fillText('Coin Trail Receipt', 50, 60);

  ctx.fillStyle = '#aaaaaa';
  ctx.font = '16px Arial';
  ctx.fillText(new Date().toLocaleString(), 50, 90);

  ctx.strokeStyle = '#00ffff';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(50, 110);
  ctx.lineTo(canvas.width - 50, 110);
  ctx.stroke();
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 24px Arial';
  ctx.fillText(`${person.name}`, 50, 150);

  ctx.font = '18px Arial';
  const netBalance = person.balance;
  const balanceText =
    netBalance >= 0
      ? `To Pay: PKR ${netBalance.toFixed(2)}`
      : `To Receive: PKR ${Math.abs(netBalance).toFixed(2)}`;

  ctx.fillStyle = netBalance >= 0 ? '#00ff88' : '#ff6b6b';
  ctx.fillText(balanceText, 50, 190);
  ctx.fillStyle = '#ffffff';
  ctx.font = '20px Arial';
  ctx.fillText('Transaction History:', 50, 240);
  ctx.font = 'bold 16px Arial';
  ctx.fillStyle = '#00ffff';
  let y = 280;

  ctx.fillText('Date', 50, y);
  ctx.fillText('Time', 150, y);
  ctx.fillText('Type', 250, y);
  ctx.fillText('Amount', 380, y);
  ctx.fillText('Balance', 520, y);
  ctx.fillText('Comment', 680, y);

  y += 10;
  ctx.strokeStyle = '#00ffff';
  ctx.beginPath();
  ctx.moveTo(50, y);
  ctx.lineTo(canvas.width - 50, y);
  ctx.stroke();

  ctx.font = '16px Arial';
  ctx.fillStyle = '#cccccc';
  y += 30;

  const getTypeForPersonView = (type: string): string => {
    switch (type) {
      case 'they_paid_me': return 'Paid';
      case 'i_paid_them': return 'Recieved';
      case 'they_owe_more': return 'To Pay';
      case 'i_owe_more': return 'Recievable';
      default: return type;
    }
  };

  person.transactions.forEach((tx) => {
    const date = new Date(tx.timestamp);
    const dateStr = date.toLocaleDateString();
    const timeStr = date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const typeStr = getTypeForPersonView(tx.type);
    const amountStr = `PKR ${tx.amount.toFixed(2)}`;
    const balanceStr = `PKR ${tx.balanceAfter.toFixed(2)}`;
    let note = tx.note?.trim() || '-';
  if (note.startsWith('Initial balance')) note = '-';
    ctx.fillText(dateStr, 50, y);
    ctx.fillText(timeStr, 150, y);
    ctx.fillText(typeStr, 250, y);
    ctx.fillText(amountStr, 380, y);
    ctx.fillText(balanceStr, 520, y);
    const maxNoteWidth = 180;
    const words = note.split(' ');
    let line = '';
    let noteY = y;
    let lines = [];

    for (let n = 0; n < words.length; n++) {
      const testLine = line + words[n] + ' ';
      if (ctx.measureText(testLine).width > maxNoteWidth && n > 0) {
        lines.push(line.trim());
        line = words[n] + ' ';
      } else {
        line = testLine;
      }
    }
    lines.push(line.trim());
    lines.forEach((ln, idx) => {
      ctx.fillText(ln, 680, noteY + idx * 18);
    });
    y += Math.max(25, lines.length * 18 + 5);
    if (y > canvas.height - 150) {
      ctx.fillText('...more transactions truncated...', 50, y);
      return;
    }
  });
  const logoImg = new Image();
  const payImg = new Image();
  logoImg.onload = () => {
    const padding = 30;
    const logoWidth = 120; // bigger logo
    const logoHeight = (logoImg.height / logoImg.width) * logoWidth;
    const x = canvas.width - logoWidth - padding;
    const y = canvas.height - logoHeight - 80;

    ctx.drawImage(logoImg, x, y, logoWidth, logoHeight);

    const payWidth = 150; // bigger pay
    const payHeight = (payImg.height / payImg.width) * payWidth;
    const payx = padding;
    const payy = canvas.height - payHeight - 80;

    ctx.drawImage(payImg, payx, payy, payWidth, payHeight);

    ctx.strokeStyle = '#00ffff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(50, canvas.height - 60);
    ctx.lineTo(canvas.width - 50, canvas.height - 60);
    ctx.stroke();

    ctx.fillStyle = '#aaaaaa';
    ctx.font = '14px Arial';
    ctx.fillText('Built with ❤️ by M. Hassan Asghar', 50, canvas.height - 30);
    this.downloadCanvas(canvas, `receipt_${person.name}_${Date.now()}.png`);
  };
payImg.src = "data:image/png;base64,"
logoImg.src = "data:image/png;base64,";
}




  generateTransactionReceipt(person: Person, transaction: Transaction): void {
    const canvas = document.createElement('canvas');
    canvas.width = 800;
    canvas.height = 500;
    const ctx = canvas.getContext('2d');

    if (!ctx) return;

    ctx.fillStyle = '#1a1a1a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 32px Arial';
    ctx.fillText('Transaction Receipt', 50, 60);

    ctx.fillStyle = '#aaaaaa';
    ctx.font = '16px Arial';
    ctx.fillText(transaction.timestamp.toLocaleString(), 50, 90);

    ctx.strokeStyle = '#00ffff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(50, 110);
    ctx.lineTo(750, 110);
    ctx.stroke();

    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 24px Arial';
    ctx.fillText(`Person: ${person.name}`, 50, 150);

    ctx.font = '18px Arial';
    const typeText = this.getTransactionTypeText(transaction.type);
    ctx.fillText(`Type: ${typeText}`, 50, 190);

    ctx.fillStyle = '#00ffff';
    ctx.font = 'bold 22px Arial';
    ctx.fillText(`Amount: PKR ${transaction.amount.toFixed(2)}`, 50, 230);

    if (transaction.note) {
      ctx.fillStyle = '#cccccc';
      ctx.font = '16px Arial';
      ctx.fillText(`Note: ${transaction.note}`, 50, 270);
    }

    ctx.fillStyle = '#ffffff';
    ctx.font = '18px Arial';
    const balanceText = transaction.balanceAfter >= 0
      ? `Balance after: They owe me PKR ${transaction.balanceAfter.toFixed(2)}`
      : `Balance after: I owe them PKR ${Math.abs(transaction.balanceAfter).toFixed(2)}`;

    ctx.fillStyle = transaction.balanceAfter >= 0 ? '#00ff88' : '#ff6b6b';
    ctx.fillText(balanceText, 50, 320);

    ctx.strokeStyle = '#00ffff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(50, canvas.height - 60);
    ctx.lineTo(750, canvas.height - 60);
    ctx.stroke();

    ctx.fillStyle = '#aaaaaa';
    ctx.font = '14px Arial';
    ctx.fillText('Built with ❤️ by M. Hassan Asghar', 50, canvas.height - 30);

    this.downloadCanvas(canvas, `transaction_${person.name}_${transaction.id}.png`);
  }

  private getTransactionTypeText(type: string): string {
    switch (type) {
      case 'they_paid_me': return 'They Paid Me';
      case 'i_paid_them': return 'I Paid Them';
      case 'they_owe_more': return 'They Owe More';
      case 'i_owe_more': return 'I Owe More';
      default: return type;
    }
  }

  private downloadCanvas(canvas: HTMLCanvasElement, filename: string): void {
    canvas.toBlob((blob) => {
      if (!blob) return;
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = filename;
      link.click();
      URL.revokeObjectURL(url);
    });
  }
}
